def simulate(s, N_total=100, N_start=1, max_turns=100):
    """
    Simulates the coloring process assuming maximal growth s per turn
    until saturation on an N_total grid.
    """
    N_green = N_start
    k = 0

    for k in range(1, max_turns + 1):
        if N_green >= N_total:
            break

        # Maximum number of cells we can add is s, limited by remaining space
        cells_to_add = min(s, N_total - N_green)

        if cells_to_add == 0:
            break

        N_green += cells_to_add

    return N_green, k

# Simulate for s=1, 2, 3
results = {}
for s_val in [1, 2, 3]:
    N_green, k = simulate(s_val)
    growth_rate = N_green / k if k > 0 else 0
    results[s_val] = {'N_green': N_green, 'k': k, 'Growth Rate (N_green/k)': growth_rate}

for s_val, data in results.items():
    print(f"s={s_val}: N_green={data['N_green']}, k={data['k']}, Growth Rate={data['Growth Rate (N_green/k)']:.3f}")
